// Demo: Bill of Materials Generator - public implementations survey
(function(){'use strict';
var DATA={"label": "Bill of Materials Generator - public implementations survey", "items": [{"name": "Laser cutting", "qty": 5, "unit": 97.32}, {"name": "Injection molding", "qty": 8, "unit": 322.08}, {"name": "DFM", "qty": 7, "unit": 436.26}, {"name": "JLCPCB", "qty": 7, "unit": 428.0}], "contingency": 15};

var sub=0;
console.log('Estimate: '+DATA.label);
DATA.items.forEach(function(it){var c=it.qty*it.unit;
  console.log('  '+it.name+': '+it.qty+' x $'+it.unit.toFixed(2)+' = $'+c.toFixed(2));sub+=c;});
var cont=sub*DATA.contingency/100, total=sub+cont;
